        if a3: state["insights"].append(f"[Claude] {a3}")
        set_task_status("T3","done"); save_state()

        set_task_status("T4","doing"); log_step("T4: szintézis (Claude)")
        src_lines = "\n".join([f"- {s['title']} | {s['url']}" for s in state["sources"][:20]])
        synth = bedrock_claude(f"Szintetizáld a forrásokat magyarul:\n{src_lines}", "Strukturált összegzés.")
        if synth: state["insights"].append(f"[Szintézis] {synth}")
        await build_report()
        set_task_status("T4","done"); save_state()

        while (datetime.datetime.now() - start).total_seconds() < max_minutes*60:
            await asyncio.sleep(2)
            pend = [t for t in state["tasks"] if t["title"].startswith("Replan") and t["status"]=="todo"]
            if pend:
                t = pend[0]
                set_task_status(t["id"],"doing"); log_step("Replan: új input")
                texts = [i.get("content","") for i in state["inputs"] if i["type"] in ("text","file_ocr")]
                blob = "\n".join(texts)[-24000:]
                state["entities"] = extract_entities(blob) if blob.strip() else state["entities"]
                q2 = (state["goal"] + " " + " ".join(state["entities"][:8])).strip()[:300] or state["goal"][:300]
                hits2 = await exa_search(q2, num=8)
                if hits2: state["sources"].extend(hits2)
                corpus2 = "\n".join([s.get("snippet","") for s in state["sources"]][-30:])[:12000]
                r1 = await cerebras_chat([{"role":"user","content":f"Frissített elemzés magyarul:\n{corpus2}"}])
                if r1: state["insights"].append(f"[Replan-Cerebras] {r1}")
                r2 = await xai_chat([{"role":"user","content":f"Új következtetések magyarul:\n{r1 or corpus2[:8000]}"}])
                if r2: state["insights"].append(f"[Replan-xAI] {r2}")
                await build_report()
                set_task_status(t["id"],"done"); save_state(); log_step("Replan kész")
        log_step("Időkeret vége")
    except Exception as e:
        log_step(f"Hiba: {e}")
    finally:
        state["running"] = False
        state["done"] = True
        await build_report()
        save_state()
        log_step("Agent kész")

@app.get("/")
async def index():
    return FileResponse("index.html")

@app.post("/start")
async def start(goal: str = Form(""), text: str = Form("")):
    if goal:
        state["goal"] = goal
    if text:
        add_input_record("text", text)
    if not state["running"]:
        asyncio.create_task(agent_run(max_minutes=60))
    return JSONResponse({"ok": True, "running": state["running"], "goal": state["goal"]})

@app.post("/upload")
async def upload(file: UploadFile = File(...)):
    content = await file.read()
    p = DATA_DIR / file.filename
    p.write_bytes(content)
    try:
        text_guess = content.decode("utf-8")
        add_input_record("file_ocr", text_guess, str(p))
    except Exception:
        add_input_record("file_bin", "", str(p))
    if state["running"]:
        if not any(t for t in state["tasks"] if t["title"].startswith("Replan") and t["status"]=="todo"):
            tid = add_task("Replan a friss input alapján"); set_task_status(tid,"todo")
    save_state()
    return JSONResponse({"ok": True, "filename": file.filename})

